package com.iminiapp.backend.dining.application;

import com.iminiapp.backend.dining.api.DiningModels.*;
import com.iminiapp.backend.identity.web.AuthenticatedPrincipal;
import com.iminiapp.backend.shared.error.*;
import org.springframework.jdbc.core.*;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.util.StringUtils;
import java.sql.*;
import java.util.*;

@Service
public class DiningManagementService {
 private final JdbcTemplate jdbc; public DiningManagementService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Transactional(readOnly=true) public List<StoreResponse> stores(){return jdbc.query("SELECT *,CAST(delivery_scope_config AS CHAR) delivery_scope_json FROM bf_dining_store ORDER BY id",(r,n)->new StoreResponse(r.getLong("id"),r.getString("store_code"),r.getString("name"),r.getString("address"),r.getString("delivery_scope_type"),r.getString("delivery_scope_json"),r.getString("contact_phone"),r.getTime("open_time").toLocalTime(),r.getTime("close_time").toLocalTime(),r.getString("status")));}
 @Transactional public StoreResponse saveStore(AuthenticatedPrincipal p,Long id,StoreRequest b){require(b!=null&&text(b.storeCode())&&text(b.name())&&text(b.address())&&b.openTime()!=null&&b.closeTime()!=null&&b.openTime().isBefore(b.closeTime()),"门店资料不完整");long u=user(p);if(id==null){id=insert("INSERT INTO bf_dining_store(store_code,name,address,contact_phone,open_time,close_time,status,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?)",b.storeCode(),b.name(),b.address(),b.contactPhone(),b.openTime(),b.closeTime(),status(b.status()),u,u);}else jdbc.update("UPDATE bf_dining_store SET store_code=?,name=?,address=?,contact_phone=?,open_time=?,close_time=?,status=?,updated_by=? WHERE id=?",b.storeCode(),b.name(),b.address(),b.contactPhone(),b.openTime(),b.closeTime(),status(b.status()),u,id);long x=id;return stores().stream().filter(v->v.id()==x).findFirst().orElseThrow();}
 @Transactional(readOnly=true) public List<TableResponse> tables(Long storeId){String w=storeId==null?"":" WHERE t.store_id=?";return jdbc.query("SELECT t.*,s.name store_name FROM bf_dining_table t JOIN bf_dining_store s ON s.id=t.store_id"+w+" ORDER BY t.id",(r,n)->new TableResponse(r.getLong("id"),r.getLong("store_id"),r.getString("store_name"),r.getString("table_code"),r.getString("name"),r.getString("table_type"),r.getInt("capacity"),r.getString("status")),storeId==null?new Object[]{}:new Object[]{storeId});}
 @Transactional public TableResponse saveTable(Long id,TableRequest b){require(b!=null&&b.storeId()!=null&&text(b.tableCode())&&text(b.name())&&b.capacity()!=null&&b.capacity()>0&&Set.of("TABLE","PRIVATE_ROOM").contains(up(b.tableType())),"餐位资料不完整");if(id==null)id=insert("INSERT INTO bf_dining_table(store_id,table_code,name,table_type,capacity,status) VALUES(?,?,?,?,?,?)",b.storeId(),b.tableCode(),b.name(),up(b.tableType()),b.capacity(),status(b.status()));else jdbc.update("UPDATE bf_dining_table SET store_id=?,table_code=?,name=?,table_type=?,capacity=?,status=? WHERE id=?",b.storeId(),b.tableCode(),b.name(),up(b.tableType()),b.capacity(),status(b.status()),id);long x=id;return tables(null).stream().filter(v->v.id()==x).findFirst().orElseThrow();}
 @Transactional(readOnly=true) public List<CategoryResponse> categories(Long storeId){String w=storeId==null?"":" WHERE c.store_id=?";return jdbc.query("SELECT c.*,s.name store_name FROM bf_dining_category c JOIN bf_dining_store s ON s.id=c.store_id"+w+" ORDER BY c.sort_order,c.id",(r,n)->new CategoryResponse(r.getLong("id"),r.getLong("store_id"),r.getString("store_name"),r.getString("category_code"),r.getString("name"),r.getInt("sort_order"),r.getString("status")),storeId==null?new Object[]{}:new Object[]{storeId});}
 @Transactional public CategoryResponse saveCategory(Long id,CategoryRequest b){require(b!=null&&b.storeId()!=null&&text(b.categoryCode())&&text(b.name()),"分类资料不完整");if(id==null)id=insert("INSERT INTO bf_dining_category(store_id,category_code,name,sort_order,status) VALUES(?,?,?,?,?)",b.storeId(),b.categoryCode(),b.name(),b.sortOrder()==null?0:b.sortOrder(),status(b.status()));else jdbc.update("UPDATE bf_dining_category SET store_id=?,category_code=?,name=?,sort_order=?,status=? WHERE id=?",b.storeId(),b.categoryCode(),b.name(),b.sortOrder()==null?0:b.sortOrder(),status(b.status()),id);long x=id;return categories(null).stream().filter(v->v.id()==x).findFirst().orElseThrow();}
 @Transactional(readOnly=true) public List<DishResponse> dishes(Long storeId,String status){List<Object>a=new ArrayList<>();StringBuilder w=new StringBuilder(" WHERE 1=1");if(storeId!=null){w.append(" AND d.store_id=?");a.add(storeId);}if(text(status)){w.append(" AND d.status=?");a.add(up(status));}return jdbc.query("""
  SELECT d.*,s.name store_name,c.name category_name,COALESCE(st.on_hand_quantity,0) on_hand_quantity,COALESCE(st.locked_quantity,0) locked_quantity,COALESCE(st.available_quantity,0) available_quantity,COALESCE(st.warning_quantity,0) warning_quantity
  FROM bf_dining_dish d JOIN bf_dining_store s ON s.id=d.store_id JOIN bf_dining_category c ON c.id=d.category_id LEFT JOIN bf_dining_stock st ON st.dish_id=d.id
  """+w+" ORDER BY d.category_id,d.id",(r,n)->dish(r),a.toArray());}
 @Transactional public DishResponse saveDish(Long id,DishRequest b){require(b!=null&&b.storeId()!=null&&b.categoryId()!=null&&text(b.dishCode())&&text(b.name())&&b.priceCent()!=null&&b.priceCent()>=0,"菜品资料不完整");if(id==null){id=insert("INSERT INTO bf_dining_dish(store_id,category_id,dish_code,name,price_cent,special_price_cent,image_url,description,recommended,special,status) VALUES(?,?,?,?,?,?,?,?,?,?,?)",b.storeId(),b.categoryId(),b.dishCode(),b.name(),b.priceCent(),b.specialPriceCent(),b.imageUrl(),b.description(),bool(b.recommended()),bool(b.special()),status(b.status()));jdbc.update("INSERT INTO bf_dining_stock(dish_id,on_hand_quantity,warning_quantity) VALUES(?,?,?)",id,b.initialStock()==null?0:b.initialStock(),b.warningQuantity()==null?10:b.warningQuantity());}else{jdbc.update("UPDATE bf_dining_dish SET store_id=?,category_id=?,dish_code=?,name=?,price_cent=?,special_price_cent=?,image_url=?,description=?,recommended=?,special=?,status=? WHERE id=?",b.storeId(),b.categoryId(),b.dishCode(),b.name(),b.priceCent(),b.specialPriceCent(),b.imageUrl(),b.description(),bool(b.recommended()),bool(b.special()),status(b.status()),id);if(b.warningQuantity()!=null)jdbc.update("UPDATE bf_dining_stock SET warning_quantity=? WHERE dish_id=?",b.warningQuantity(),id);}long x=id;return dishes(null,null).stream().filter(v->v.id()==x).findFirst().orElseThrow();}
 @Transactional public DishResponse adjustStock(long dishId,StockAdjustRequest b){require(b!=null&&b.quantity()!=null&&b.quantity()>0&&Set.of("IN","OUT").contains(up(b.operation()))&&text(b.idempotencyKey()),"库存调整参数不完整");Integer exists=jdbc.queryForObject("SELECT COUNT(*) FROM bf_dining_stock_log WHERE idempotency_key=?",Integer.class,b.idempotencyKey());if(exists!=null&&exists>0)return dishes(null,null).stream().filter(v->v.id()==dishId).findFirst().orElseThrow();int delta="IN".equals(up(b.operation()))?b.quantity():-b.quantity();int changed=jdbc.update("UPDATE bf_dining_stock SET on_hand_quantity=on_hand_quantity+?,version=version+1 WHERE dish_id=? AND on_hand_quantity+?>=locked_quantity",delta,dishId,delta);if(changed!=1)throw conflict("库存不足或菜品不存在");jdbc.update("INSERT INTO bf_dining_stock_log(dish_id,change_type,quantity_delta,on_hand_after,locked_after,idempotency_key,remark) SELECT ?,?,?,on_hand_quantity,locked_quantity,?,? FROM bf_dining_stock WHERE dish_id=?",dishId,up(b.operation()),delta,b.idempotencyKey(),b.remark(),dishId);return dishes(null,null).stream().filter(v->v.id()==dishId).findFirst().orElseThrow();}
 @Transactional(readOnly=true) public List<PackageResponse> packages(Long storeId){String w=storeId==null?"":" WHERE p.store_id=?";return jdbc.query("SELECT p.*,s.name store_name FROM bf_dining_package p JOIN bf_dining_store s ON s.id=p.store_id"+w+" ORDER BY p.id",(r,n)->new PackageResponse(r.getLong("id"),r.getLong("store_id"),r.getString("store_name"),r.getString("package_code"),r.getString("name"),r.getLong("price_cent"),r.getString("image_url"),r.getString("description"),r.getBoolean("recommended"),r.getString("status"),packageItems(r.getLong("id"))),storeId==null?new Object[]{}:new Object[]{storeId});}
 @Transactional public PackageResponse savePackage(Long id,PackageRequest b){require(b!=null&&b.storeId()!=null&&text(b.packageCode())&&text(b.name())&&b.priceCent()!=null&&b.priceCent()>=0&&b.items()!=null&&!b.items().isEmpty(),"套餐资料不完整");if(id==null)id=insert("INSERT INTO bf_dining_package(store_id,package_code,name,price_cent,image_url,description,recommended,status) VALUES(?,?,?,?,?,?,?,?)",b.storeId(),b.packageCode(),b.name(),b.priceCent(),b.imageUrl(),b.description(),bool(b.recommended()),status(b.status()));else{jdbc.update("UPDATE bf_dining_package SET store_id=?,package_code=?,name=?,price_cent=?,image_url=?,description=?,recommended=?,status=? WHERE id=?",b.storeId(),b.packageCode(),b.name(),b.priceCent(),b.imageUrl(),b.description(),bool(b.recommended()),status(b.status()),id);jdbc.update("DELETE FROM bf_dining_package_item WHERE package_id=?",id);}for(PackageItemRequest i:b.items()){require(i.dishId()!=null&&i.quantity()!=null&&i.quantity()>0,"套餐菜品不合法");jdbc.update("INSERT INTO bf_dining_package_item(package_id,dish_id,quantity) VALUES(?,?,?)",id,i.dishId(),i.quantity());}long x=id;return packages(null).stream().filter(v->v.id()==x).findFirst().orElseThrow();}
 private List<PackageItemResponse> packageItems(long id){return jdbc.query("SELECT i.dish_id,d.name,i.quantity FROM bf_dining_package_item i JOIN bf_dining_dish d ON d.id=i.dish_id WHERE i.package_id=?",(r,n)->new PackageItemResponse(r.getLong(1),r.getString(2),r.getInt(3)),id);}
 private DishResponse dish(ResultSet r)throws SQLException{long price=r.getBoolean("special")&&r.getObject("special_price_cent")!=null?r.getLong("special_price_cent"):r.getLong("price_cent");int available=r.getInt("available_quantity"),warning=r.getInt("warning_quantity");return new DishResponse(r.getLong("id"),r.getLong("store_id"),r.getString("store_name"),r.getLong("category_id"),r.getString("category_name"),r.getString("dish_code"),r.getString("name"),r.getLong("price_cent"),r.getObject("special_price_cent",Long.class),price,r.getString("image_url"),r.getString("description"),r.getBoolean("recommended"),r.getBoolean("special"),r.getString("status"),r.getInt("on_hand_quantity"),r.getInt("locked_quantity"),available,warning,available<=warning);}
 private long insert(String sql,Object...a){GeneratedKeyHolder k=new GeneratedKeyHolder();jdbc.update(c->{PreparedStatement p=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS);for(int i=0;i<a.length;i++)p.setObject(i+1,a[i]);return p;},k);return Objects.requireNonNull(k.getKey()).longValue();}
 private long user(AuthenticatedPrincipal p){jdbc.update("INSERT INTO bf_user(wechat_openid,nickname,status) VALUES(?,?,'ACTIVE') ON DUPLICATE KEY UPDATE nickname=VALUES(nickname)",p.databaseOpenId(),p.displayName());return jdbc.queryForObject("SELECT id FROM bf_user WHERE wechat_openid=?",Long.class,p.databaseOpenId());}
 private void require(boolean ok,String m){if(!ok)throw new BusinessException(CommonErrorCode.INVALID_REQUEST,m);}private BusinessException conflict(String m){return new BusinessException(CommonErrorCode.INVENTORY_CONFLICT,m);}private boolean text(String s){return StringUtils.hasText(s);}private String up(String s){return s==null?"":s.trim().toUpperCase(Locale.ROOT);}private String status(String s){String v=up(s);return Set.of("ACTIVE","INACTIVE").contains(v)?v:"ACTIVE";}private int bool(Boolean b){return Boolean.TRUE.equals(b)?1:0;}
}
